@Component(immediate = true, service = MVCResourceCommand.class, property = {
		"javax.portlet.name=" + PresentatoreFormsPortletKeys.PRESENTATOREFORMS,
		"mvc.command.name=" + PresentatoreFormsPortletKeys.SALVA_FORM_INTEGRATIVO
})
public class SalvaFormIntegrativoResourceCommand extends BaseMVCResourceCommand {

	private static final Gson gson = new Gson();
	private static final Log log = LogFactoryUtil.getLog(SalvaFormIntegrativoResourceCommand.class);


	@Reference
	private FormLocalService formLocalService;

	@Reference
	private DefinizioneAllegatoLocalService definizioneAllegatoLocalService;

	@Reference
	private IstanzaDomandaBandoLocalService istanzaDomandaBandoLocalService;

	@Reference
	private DomandaBandoLocalService domandaBandoLocalService;

	@Reference
	private StatoDomandaLocalService statoDomandaLocalService;

	@Reference
	private AuditService auditService;

	@Reference
	private AllegatoDomandaBandoLocalService allegatoDomandaBandoLocalService;

	@Reference
	private PresentatoreFormFrontendService presentatoreFormFrontendService;

	@Override
	protected void doServeResource(ResourceRequest request, ResourceResponse response) throws Exception {
		String inputJson = ParamUtil.getString(request, "json");
		long istanzaDomandaBandoId = ParamUtil.getLong(request, "istanzaDomandaBandoId");

		JsonObject payload;

		try {
			ThemeDisplay themeDisplay = (ThemeDisplay) request.getAttribute(WebKeys.THEME_DISPLAY);

			boolean compilaDocumentoEsecuzione = ParamUtil.getBoolean(request, PresentatoreFormsPortletKeys.COMPILA_DOCUMENTO_ESECUZIONE);
			IstanzaDomandaBando istanzaDomandaBando = istanzaDomandaBandoLocalService.getIstanzaDomandaBando(istanzaDomandaBandoId);

			if (themeDisplay.getUserId() != istanzaDomandaBando.getUserId()) {
				throw new UserMismatchException();
			}

			Form form = formLocalService.getForm(istanzaDomandaBando.getFormId());
			List<DefinizioneAllegato> defAllegati = definizioneAllegatoLocalService.getListaDefinizioneAllegatoByFormId(form.getFormId());
			form.setListaDefinizioneAllegato(defAllegati);

			FormData formData = AlpacaUtil.loadFormData(form, null, true, themeDisplay.getPortalURL());

			Object dataObject = gson.fromJson(inputJson, Object.class);
			formData.getAlpaca().setData(dataObject);

			istanzaDomandaBando.setJson(gson.toJson(formData));

			String statoCorrente = istanzaDomandaBando.getStato();
			if (StatoIntegrazioneDomandaBandoEnum.NON_VALIDATA.name().equals(statoCorrente)
					|| StatoIntegrazioneDomandaBandoEnum.BOZZA.name().equals(statoCorrente)) {
				istanzaDomandaBando.setStato(StatoIntegrazioneDomandaBandoEnum.BOZZA.name());
			}

			istanzaDomandaBandoLocalService.updateIstanzaDomandaBando(istanzaDomandaBando);

			payload = new JsonObject();

			List<DefinizioneAllegatoDTO> definizioneAllegati = AllegatoUtil.retrieveAllegati(istanzaDomandaBando, form);
			List<AllegatoDomandaBando> allegatoDomandaBandoList = allegatoDomandaBandoLocalService.getListaAllegatiByIstanzaDomandaBandoId(istanzaDomandaBando.getIstanzaDomandaBandoId());
			List<Long> allegatoDomandaBandoIds = allegatoDomandaBandoLocalService.getAllegatiByIstanzaDomandaBandoIdAndPrincipale(istanzaDomandaBando.getIstanzaDomandaBandoId(),false);

			Set<Long> allegatiVariatiIds = presentatoreFormFrontendService.recuperaAllegatiVariatiIds(definizioneAllegati, allegatoDomandaBandoIds);

			boolean ricaricamentoAllegati = Validator.isNotNull(allegatiVariatiIds) && !allegatiVariatiIds.isEmpty();

			List<AllegatoDomandaBando> allegatiVariati = new ArrayList<>();
			if (ricaricamentoAllegati) {
				for (Long idVariato: allegatiVariatiIds) {
					Optional<AllegatoDomandaBando> allegatoDomandaBando = allegatoDomandaBandoList.stream().filter(adb -> adb.getDefinizioneAllegatoId() == idVariato).findFirst();
					allegatoDomandaBando.ifPresent(allegatiVariati::add);
				}
			}
			if (!allegatiVariati.isEmpty()) {
				payload.addProperty("status", "KO");
				JsonArray allegatiVariatiJson = new JsonArray();
				for (AllegatoDomandaBando allegatoDomandaBando: allegatiVariati) {
					JsonObject allegatoVariato = new JsonObject();
					allegatoVariato.addProperty("titolo", allegatoDomandaBando.getTitolo());
					allegatoVariato.addProperty("nome", allegatoDomandaBando.getNome());
					allegatiVariatiJson.add(allegatoVariato);
				}
				payload.add("allegatiVariati", allegatiVariatiJson);
			} else {
				payload.addProperty("status", "OK");
			}
		} catch (Exception e) {
			auditService.saveErrorLog(request, e.getMessage());
			log.error(e);

			payload = new JsonObject();
			payload.addProperty("status", "KO");
		}

		String json = payload.toString();
		response.getPortletOutputStream().write(json.getBytes());
	}

}

