package it.servizidigitali.gestionebandi.service.impl;

import com.liferay.portal.aop.AopService;

import it.servizidigitali.gestionebandi.model.DomandaBandoDatoAggiuntivo;
import it.servizidigitali.gestionebandi.service.base.DomandaBandoDatoAggiuntivoLocalServiceBaseImpl;

import java.util.Collections;
import java.util.List;

import org.osgi.service.component.annotations.Component;

/**
 * @author Brian Wing Shun Chan
 */
@Component(
	property = "model.class.name=it.servizidigitali.gestionebandi.model.DomandaBandoDatoAggiuntivo",
	service = AopService.class
)
public class DomandaBandoDatoAggiuntivoLocalServiceImpl
	extends DomandaBandoDatoAggiuntivoLocalServiceBaseImpl {

	@Override
	public List<DomandaBandoDatoAggiuntivo> getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(List<Long> domandaBandoIds, List<String> chiavi) {
		return domandaBandoDatoAggiuntivoFinder.findDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(domandaBandoIds, chiavi);
	}

    @Override
    public long countDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(Long domandaBandoId, List<String> chiavi) {
        return domandaBandoDatoAggiuntivoFinder.countDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(domandaBandoId, chiavi);
    }

    @Override
    public DomandaBandoDatoAggiuntivo addDomandaBandoDatoAggiuntivo(
            DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo) {

        long domandaBandoId = domandaBandoDatoAggiuntivo.getDomandaBandoId();
        String chiave = domandaBandoDatoAggiuntivo.getChiave();

        int maxProgressivo = domandaBandoDatoAggiuntivoFinder
                .findMaxProgressivoByDomandaBandoIdAndChiave(domandaBandoId, chiave);

        domandaBandoDatoAggiuntivo.setProgressivo(maxProgressivo + 1);
        return domandaBandoDatoAggiuntivoPersistence.update(domandaBandoDatoAggiuntivo);
    }
}

